883	/// Tracks entity handle allocations to detect leaks.
884	///
885	/// The leak detector is enabled in tests and when the `leak-detection` feature is active.
886	/// It tracks every `Entity<T>` and `AnyEntity` handle that is created and released,
887	/// allowing you to verify that all handles to an entity have been properly dropped.
888	///
889	/// # How do leaks happen?
890	///
891	/// Entities are reference-counted structures that can own other entities
892	/// allowing to form cycles. If such a strong-reference counted cycle is
893	/// created, all participating strong entities in this cycle will effectively
894	/// leak as they cannot be released anymore.
895	///
896	/// Cycles can also happen if an entity owns a task or subscription that it
897	/// itself owns a strong reference to the entity again.
898	///
899	/// # Usage
900	///
901	/// You can use `WeakEntity::assert_released` or `AnyWeakEntity::assert_released`
902	/// to verify that an entity has been fully released:
903	///
904	/// ```ignore
905	/// let entity = cx.new(|_| MyEntity::new());
906	/// let weak = entity.downgrade();
907	/// drop(entity);
908	///
909	/// // This will panic if any handles to the entity are still alive
910	/// weak.assert_released();
911	/// ```
912	///
913	/// # Debugging Leaks
914	///
915	/// When a leak is detected, the detector will panic with information about the leaked
916	/// handles. To see where the leaked handles were allocated, set the `LEAK_BACKTRACE`
917	/// environment variable:
918	///
919	/// ```bash
920	/// LEAK_BACKTRACE=1 cargo test my_test
921	/// ```
922	///
923	/// This will capture and display backtraces for each leaked handle, helping you
924	/// identify where leaked handles were created.
925	///
926	/// # How It Works
927	///
928	/// - When an entity handle is created (via `Entity::new`, `Entity::clone`, or
929	///   `WeakEntity::upgrade`), `handle_created` is called to register the handle.
930	/// - When a handle is dropped, `handle_released` removes it from tracking.
931	/// - `assert_released` verifies that no handles remain for a given entity.
932	#[cfg(any(test, feature = "leak-detection"))]
933	pub(crate) struct LeakDetector {
934	    next_handle_id: u64,
935	    entity_handles: HashMap<EntityId, EntityLeakData>,
936	}
937	
938	/// A snapshot of the set of alive entities at a point in time.
939	///
940	/// Created by [`LeakDetector::snapshot`]. Can later be passed to
941	/// [`LeakDetector::assert_no_new_leaks`] to verify that no new entity
942	/// handles remain between the snapshot and the current state.
943	#[cfg(any(test, feature = "leak-detection"))]
944	pub struct LeakDetectorSnapshot {
945	    entity_ids: collections::HashSet<EntityId>,
946	}
