948	#[cfg(any(test, feature = "leak-detection"))]
949	struct EntityLeakData {
950	    handles: HashMap<HandleId, Option<backtrace::Backtrace>>,
951	    type_name: &'static str,
952	}
953	
954	#[cfg(any(test, feature = "leak-detection"))]
955	impl LeakDetector {
956	    /// Records that a new handle has been created for the given entity.
957	    ///
958	    /// Returns a unique `HandleId` that must be passed to `handle_released` when
959	    /// the handle is dropped. If `LEAK_BACKTRACE` is set, captures a backtrace
960	    /// at the allocation site.
961	    #[track_caller]
962	    pub fn handle_created(
963	        &mut self,
964	        entity_id: EntityId,
965	        type_name: Option<&'static str>,
966	    ) -> HandleId {
967	        let id = gpui_util::post_inc(&mut self.next_handle_id);
968	        let handle_id = HandleId { id };
969	        let handles = self
970	            .entity_handles
971	            .entry(entity_id)
972	            .or_insert_with(|| EntityLeakData {
973	                handles: HashMap::default(),
974	                type_name: type_name.unwrap_or("<unknown>"),
975	            });
976	        handles.handles.insert(
977	            handle_id,
978	            LEAK_BACKTRACE.then(backtrace::Backtrace::new_unresolved),
979	        );
980	        handle_id
981	    }
982	
983	    /// Records that a handle has been released (dropped).
984	    ///
985	    /// This removes the handle from tracking. The `handle_id` should be the same
986	    /// one returned by `handle_created` when the handle was allocated.
987	    pub fn handle_released(&mut self, entity_id: EntityId, handle_id: HandleId) {
988	        if let std::collections::hash_map::Entry::Occupied(mut data) =
989	            self.entity_handles.entry(entity_id)
990	        {
991	            data.get_mut().handles.remove(&handle_id);
992	            if data.get().handles.is_empty() {
993	                data.remove();
994	            }
995	        }
996	    }
997	
998	    /// Asserts that all handles to the given entity have been released.
999	    ///
1000	    /// # Panics
1001	    ///
1002	    /// Panics if any handles to the entity are still alive. The panic message
1003	    /// includes backtraces for each leaked handle if `LEAK_BACKTRACE` is set,
1004	    /// otherwise it suggests setting the environment variable to get more info.
1005	    pub fn assert_released(&mut self, entity_id: EntityId) {
1006	        use std::fmt::Write as _;
1007	
1008	        if let Some(data) = self.entity_handles.remove(&entity_id) {
1009	            let mut out = String::new();
1010	            for (_, backtrace) in data.handles {
1011	                if let Some(mut backtrace) = backtrace {
1012	                    backtrace.resolve();
1013	                    let backtrace = BacktraceFormatter(backtrace);
1014	                    writeln!(out, "Leaked handle:\n{:?}", backtrace).unwrap();
1015	                } else {
1016	                    writeln!(
1017	                        out,
1018	                        "Leaked handle: (export LEAK_BACKTRACE to find allocation site)"
1019	                    )
1020	                    .unwrap();
1021	                }
1022	            }
1023	            panic!("Handles for {} leaked:\n{out}", data.type_name);
1024	        }
1025	    }
1026	
1027	    /// Captures a snapshot of all entity IDs that currently have alive handles.
1028	    ///
1029	    /// The returned [`LeakDetectorSnapshot`] can later be passed to
1030	    /// [`assert_no_new_leaks`](Self::assert_no_new_leaks) to verify that no
1031	    /// entities created after the snapshot are still alive.
1032	    pub fn snapshot(&self) -> LeakDetectorSnapshot {
1033	        LeakDetectorSnapshot {
1034	            entity_ids: self.entity_handles.keys().copied().collect(),
1035	        }
1036	    }
1037	
1038	    /// Asserts that no entities created after `snapshot` still have alive handles.
1039	    ///
1040	    /// Entities that were already tracked at the time of the snapshot are ignored,
1041	    /// even if they still have handles. Only *new* entities (those whose
1042	    /// `EntityId` was not present in the snapshot) are considered leaks.
1043	    ///
1044	    /// # Panics
1045	    ///
1046	    /// Panics if any new entity handles exist. The panic message lists every
1047	    /// leaked entity with its type name, and includes allocation-site backtraces
1048	    /// when `LEAK_BACKTRACE` is set.
1049	    pub fn assert_no_new_leaks(&self, snapshot: &LeakDetectorSnapshot) {
1050	        use std::fmt::Write as _;
1051	
1052	        let mut out = String::new();
1053	        for (entity_id, data) in &self.entity_handles {
1054	            if snapshot.entity_ids.contains(entity_id) {
1055	                continue;
1056	            }
1057	            for (_, backtrace) in &data.handles {
1058	                if let Some(backtrace) = backtrace {
1059	                    let mut backtrace = backtrace.clone();
1060	                    backtrace.resolve();
1061	                    let backtrace = BacktraceFormatter(backtrace);
1062	                    writeln!(
1063	                        out,
1064	                        "Leaked handle for entity {} ({entity_id:?}):\n{:?}",
1065	                        data.type_name, backtrace
1066	                    )
1067	                    .unwrap();
1068	                } else {
1069	                    writeln!(
1070	                        out,
1071	                        "Leaked handle for entity {} ({entity_id:?}): (export LEAK_BACKTRACE to find allocation site)",
1072	                        data.type_name
1073	                    )
1074	                    .unwrap();
1075	                }
1076	            }
1077	        }
1078	
1079	        if !out.is_empty() {
1080	            panic!("New entity leaks detected since snapshot:\n{out}");
1081	        }
1082	    }
1083	}
